import React, { useState } from 'react';

function App() {
  const [files, setFiles] = useState([]);
  const [results, setResults] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleFileChange = (e) => {
    setFiles(e.target.files);
    setResults(null);
    setError(null);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!files.length) return;
    setLoading(true);
    setError(null);
    setResults(null);
    const formData = new FormData();
    for (let i = 0; i < files.length; i++) {
      formData.append('files', files[i]);
    }
    try {
      const res = await fetch('http://localhost:5000/extract-outline', {
        method: 'POST',
        body: formData,
      });
      if (!res.ok) throw new Error('Failed to extract outline');
      const data = await res.json();
      setResults(data);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ maxWidth: 700, margin: '2rem auto', fontFamily: 'sans-serif' }}>
      <h1>PDF Outline Extractor</h1>
      <form onSubmit={handleSubmit}>
        <input
          type="file"
          accept="application/pdf"
          multiple
          onChange={handleFileChange}
        />
        <button type="submit" disabled={loading || !files.length} style={{ marginLeft: 10 }}>
          {loading ? 'Processing...' : 'Extract Outline'}
        </button>
      </form>
      {error && <div style={{ color: 'red', marginTop: 10 }}>{error}</div>}
      {results && (
        <div style={{ marginTop: 30 }}>
          <h2>Results</h2>
          {Object.entries(results).map(([filename, outline]) => (
            <div key={filename} style={{ marginBottom: 30, padding: 15, border: '1px solid #ccc', borderRadius: 8 }}>
              <h3>{filename}</h3>
              <div><strong>Title:</strong> {outline.title}</div>
              <div style={{ marginTop: 10 }}>
                <strong>Outline:</strong>
                <ul>
                  {outline.outline.map((item, idx) => (
                    <li key={idx}>
                      <span style={{ fontWeight: item.level === 'H1' ? 'bold' : item.level === 'H2' ? 600 : 400 }}>
                        [{item.level}] {item.text}
                      </span>
                      {` (Page ${item.page})`}
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default App;
